limitRows(rows, limit) {
  let shown = 0, total = 0;
  const out = [];
  for (const r of rows) {
    if (r.__g) { out.push(r); continue; }
    total++;
    if (shown < limit) { shown++; out.push(r); }
  }
  // a group header stays when its group is folded, or when at least one of its members is drawn
  const kept = out.filter((r, i) => !r.__g || r.folded || (out[i + 1] && !out[i + 1].__g));
  return { rows: kept, shown, total };
},
